const artworkUI=()=>ARTWORK_UI[lang]||ARTWORK_UI.en;
const ART_DB='artbridge.artwork.files.v1', ART_STORE='files';
function artworkList(r){return Array.isArray(r?.meta?.artworks)?r.meta.artworks:[];}
function openArtworkDb(){return new Promise((resolve,reject)=>{const q=indexedDB.open(ART_DB,1);q.onupgradeneeded=()=>{if(!q.result.objectStoreNames.contains(ART_STORE))q.result.createObjectStore(ART_STORE);};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
async function artworkPut(key,blob){const db=await openArtworkDb();return new Promise((resolve,reject)=>{const tx=db.transaction(ART_STORE,'readwrite');tx.objectStore(ART_STORE).put(blob,key);tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>{db.close();reject(tx.error);};});}
async function artworkGet(key){const db=await openArtworkDb();return new Promise((resolve,reject)=>{const tx=db.transaction(ART_STORE,'readonly'),q=tx.objectStore(ART_STORE).get(key);q.onsuccess=()=>{db.close();resolve(q.result||null);};q.onerror=()=>{db.close();reject(q.error);};});}
const artworkKey=(pid,aid)=>`${pid}:${aid}`;
async function sha256Blob(blob){const buf=await blob.arrayBuffer(),digest=await crypto.subtle.digest('SHA-256',buf);return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');}
function artworkExchange(r){const c=artworkUI(),items=artworkList(r);return `<section class="artwork-exchange"><div class="artwork-exchange-head"><div><span class="pill">${esc(c.title)}</span><h3>${esc(c.title)}</h3><p class="helper">${esc(c.help)}</p></div></div><form id="artwork-upload-form" data-project-id="${esc(r.id)}" class="artwork-upload-form"><label class="field"><span>${esc(c.artist)}</span><select name="artist" required><option value="a">${esc(r.meta.artist_a)}</option><option value="b">${esc(r.meta.artist_b)}</option></select></label><label class="field artwork-file-field"><span>${esc(c.file)}</span><input type="file" name="file" accept="image/png,image/jpeg,image/webp" required></label><label class="field"><span>${esc(c.note)}</span><input name="note" maxlength="240" placeholder="${esc(c.note)}"></label><button class="button dark" type="submit">${esc(c.upload)}</button></form><p class="artwork-copy-warning">${esc(c.copyWarning)}</p><div class="artwork-exchange-list">${items.length?items.map((a,i)=>`<article class="artwork-card" data-artwork-id="${esc(a.id)}"><div class="artwork-preview-wrap"><img data-artwork-preview="${esc(a.id)}" alt="${esc(a.name||'Artwork')}" hidden><div class="artwork-preview-missing">${esc(c.missing)}</div><span class="artwork-watermark">ArtBridge · ${esc(r.id)}</span></div><div class="artwork-card-body"><div class="artwork-card-top"><div><strong>${esc(a.name||'Artwork')}</strong><p class="helper">${esc(c.version)} ${esc(a.version)} · ${esc(a.artist==='a'?r.meta.artist_a:r.meta.artist_b)} · ${esc(new Date(a.uploaded_at).toLocaleString(lang))}</p></div><span class="verified-badge">✓ ${esc(c.verified)}</span></div>${a.note?`<p>${esc(a.note)}</p>`:''}<details class="artwork-proof"><summary>${esc(c.proof)}</summary><p><strong>${esc(c.hash)}</strong><br><code>${esc(a.sha256)}</code></p>${a.anchor?`<p><strong>${esc(c.tx)}</strong><br><code>${esc(a.anchor.txHash)}</code><br><span class="helper">Chain ${esc(a.anchor.chainId)} · ${esc(a.anchor.anchoredAt)}</span></p>`:''}</details><div class="button-row artwork-actions"><button class="button" data-download-protected="${esc(a.id)}" data-project-id="${esc(r.id)}">${esc(c.protect)}</button>${a.anchor?`<button class="button" data-verify-anchor="${esc(a.id)}" data-project-id="${esc(r.id)}">${esc(c.verifyChain)}</button>`:`<button class="button" data-anchor-artwork="${esc(a.id)}" data-project-id="${esc(r.id)}">${esc(c.anchor)}</button>`}</div>${a.anchor?`<p class="anchored-state">✓ ${esc(c.anchored)}</p>`:`<p class="helper">${esc(c.walletNeeded)}</p>`}</div></article>`).join(''):`<p class="helper">${esc(c.noArt)}</p>`}</div></section>`;}
async function hydrateArtworkPreviews(r){for(const a of artworkList(r)){try{const blob=await artworkGet(artworkKey(r.id,a.id)),img=document.querySelector(`[data-artwork-preview="${CSS.escape(a.id)}"]`);if(blob&&img){const url=URL.createObjectURL(blob);img.src=url;img.hidden=false;const missing=img.parentElement.querySelector('.artwork-preview-missing');if(missing)missing.hidden=true;img.onload=()=>setTimeout(()=>URL.revokeObjectURL(url),30000);}}catch{}}}
function projectCardArtwork(r){const items=artworkList(r),latest=items[items.length-1],title=projectDisplayTitle(r);return `<div class="project-card-artwork${latest?" has-artwork":""}" data-project-card="${esc(r.id)}">${latest?`<img data-project-card-preview="${esc(r.id)}" alt="${esc(latest.name||title)}" hidden>`:""}<div class="project-card-artwork-placeholder"><span>${esc((title||"A").charAt(0))}</span><small>${esc(lang==="ko"?"작품 미리보기":lang==="sw"?"Muhtasari wa kazi":"Artwork preview")}</small></div></div>`;}
async function hydrateProjectCardPreviews(list){for(const r of list){const items=artworkList(r),latest=items[items.length-1];if(!latest)continue;try{const blob=await artworkGet(artworkKey(r.id,latest.id)),img=document.querySelector(`[data-project-card-preview="${CSS.escape(r.id)}"]`);if(blob&&img){const url=URL.createObjectURL(blob);img.src=url;img.hidden=false;img.closest(".project-card-artwork")?.classList.add("loaded");img.onload=()=>setTimeout(()=>URL.revokeObjectURL(url),30000);}}catch{}}}
async function protectedArtworkBlob(r,a,blob){const bitmap=await createImageBitmap(blob),canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');canvas.width=bitmap.width;canvas.height=bitmap.height;ctx.drawImage(bitmap,0,0);const recipient=a.artist==='a'?r.meta.artist_b:r.meta.artist_a,band=Math.max(54,Math.round(canvas.height*0.07));ctx.fillStyle='rgba(5,20,45,.72)';ctx.fillRect(0,canvas.height-band,canvas.width,band);ctx.fillStyle='white';ctx.font=`${Math.max(16,Math.round(band*.28))}px sans-serif`;ctx.textBaseline='middle';const stamp=`ArtBridge · Shared with ${recipient} · ${r.id} · ${a.sha256.slice(0,12)}`;ctx.fillText(stamp,Math.max(16,band*.25),canvas.height-band/2);bitmap.close();return await new Promise(resolve=>canvas.toBlob(resolve,'image/png',.94));}
function artworkProofText(r){const list=artworkList(r);if(!list.length)return '';return `\n\nDIGITAL ARTWORK INTEGRITY RECORDS\n`+list.map(a=>`${a.name||'Artwork'} · Version ${a.version}\nUploaded by: ${a.artist==='a'?r.meta.artist_a:r.meta.artist_b}\nSHA-256: ${a.sha256}${a.anchor?`\nBlockchain: chain ${a.anchor.chainId} · ${a.anchor.txHash}`:''}`).join('\n\n');}

const agreementUI=()=>AGREEMENT_UI[lang]||AGREEMENT_UI.en;
function agreementState(r){return r?.meta?.agreement_state||'draft';}
function signatureData(r){const s=r?.meta?.signatures||{};return {a:s.a||null,b:s.b||null};}
function signatureLabel(value){if(!value)return agreementUI().awaiting;const raw=typeof value==='object'?(value.signed_at||value.date):value;try{return new Date(raw).toLocaleString(lang);}catch{return String(raw||'');}}
function signatureImage(value){return value&&typeof value==='object'&&value.image?value.image:'';}
function projectStatus(r){const state=agreementState(r);if(state==='awaiting')return {en:'Signing',ko:'Signing',sw:'Signing'}[lang];if(state==='signed')return {en:'Confirmed',ko:'Confirmed',sw:'Confirmed'}[lang];if(state==='documented')return {en:'Documented',ko:'Documented',sw:'Documented'}[lang];return {en:'Review',ko:'Review',sw:'Review'}[lang];}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const textFor=(r,l=lang)=>r?.[l]||r?.[r.source_language]||'';
const uid=()=>crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function setLanguage(value){lang=value;document.documentElement.lang=lang;document.body.lang=lang;$('#language').value=lang;localStorage.setItem('artbridge.language',lang);$$('[data-i18n]').forEach(n=>n.textContent=t(n.dataset.i18n));$$('[data-i18n-html]').forEach(n=>n.innerHTML=t(n.dataset.i18nHtml));$$('[data-placeholder]').forEach(n=>n.placeholder=t(n.dataset.placeholder));$$('[data-i18n-alt]').forEach(n=>n.alt=t(n.dataset.i18nAlt));$$('[data-lang]').forEach(n=>n.hidden=n.dataset.lang!==lang);document.title=t('docTitle');$$('[data-bilingual-caption]').forEach(n=>n.lang=lang==='ko'?'ko':'sw');$('#close-modal').setAttribute('aria-label',t('close'));renderDiscover();renderStudio();if(window.ArtBridgeApply)ArtBridgeApply.render(lang);if(window.ArtBridgeHome)ArtBridgeHome.renderArtists(lang);setVideoLanguage();}
function setVideoLanguage(){const f=document.getElementById('ezekiel-video');if(!f)return;const cc=lang==='ko'?'ko':'en';const src=`https://www.youtube-nocookie.com/embed/${f.dataset.youtube}?cc_load_policy=1&cc_lang_pref=${cc}&hl=${cc}&rel=0&modestbranding=1`;if(f.src!==src)f.src=src;}
function showPage(){let route=location.hash.slice(1)||'home';const anchorPage={story:'home',how:'home','ezekiel-voice':'meeting','grace-voice':'meeting','grace-direction':'meeting'};const anchor=anchorPage[route]?route:null;if(anchor)route=anchorPage[anchor];if(!['home','discover','studio','apply','meeting','about','research'].includes(route))route='home';$$('.page').forEach(n=>n.hidden=n.id!==route);$$('[data-route]').forEach(n=>{n.classList.toggle('active',n.dataset.route===route);if(n.dataset.route===route)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});if(route==='discover')renderDiscover();if(route==='studio')renderStudio();if(anchor)requestAnimationFrame(()=>$('#'+anchor).scrollIntoView());else window.scrollTo(0,0);}
function openModal(html,label='ARTBRIDGE / STUDIO'){$('#modal-label').textContent=label;$('#modal-content').innerHTML=html;$('#modal').showModal();}
function heading(title){return `<h2 id="modal-title">${esc(title)}</h2>`;}
function closeModal(){$('#modal').close();$('#modal').classList.remove('project-modal');activeRecord=null;activeDocument=null;}
$('#close-modal').addEventListener('click',closeModal);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')&&e.clientX){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#language').addEventListener('change',e=>setLanguage(e.target.value));window.addEventListener('hashchange',showPage);
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(quoted){quoted=false;}else if(!cell){quoted=true;}else throw Error('Malformed CSV');}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.length))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Unclosed CSV quote');row.push(cell);if(row.some(x=>x.length))rows.push(row);if(!rows.length)return [];const headers=rows.shift();headers[0]=headers[0].replace(/^\uFEFF/,'');if(new Set(headers).size!==headers.length)throw Error('Duplicate header');return rows.map(r=>{if(r.length!==headers.length)throw Error('Column count');return Object.fromEntries(headers.map((h,i)=>[h,r[i]]));});}
function csvCell(v){let s=String(v??'');if(/^[\s]*['=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
const CSV_FIELDS=['id','kind','source_language','en','ko','sw','translation_status','updated_at','payload_json'];
function toCSV(items){return '\uFEFF'+CSV_FIELDS.map(csvCell).join(',')+'\r\n'+items.map(r=>CSV_FIELDS.map(k=>csvCell(k==='payload_json'?JSON.stringify(r.meta||{}):r[k])).join(',')).join('\r\n');}
function fromCSV(text){return parseCSV(text).map(row=>{for(const k of Object.keys(row)){if(row[k].startsWith("'")&&/^[\s]*['=+@\-\t\r]/.test(row[k].slice(1)))row[k]=row[k].slice(1);}if(!CSV_FIELDS.every(k=>k in row)||!['profile','project','note'].includes(row.kind)||!langs.includes(row.source_language)||!row.id||row.id.length>100)throw Error('Invalid record');const meta=JSON.parse(row.payload_json);if(!meta||typeof meta!=='object'||Array.isArray(meta))throw Error('Invalid metadata');for(const k of ['en','ko','sw'])if(row[k].length>20000)throw Error('Too long');const result=Object.fromEntries(CSV_FIELDS.filter(k=>k!=='payload_json').map(k=>[k,row[k]]));result.meta=meta;validateLocalRecord(result);return result;});}
function validateLocalRecord(r){
 if(!/^[A-Za-z0-9_-]{1,100}$/.test(r.id)||!r[r.source_language]?.trim()||!['pending','machine','reviewed'].includes(r.translation_status)||!Number.isFinite(Date.parse(r.updated_at)))throw Error('Invalid record');
 const m=r.meta;
 if(r.kind==='profile'){
  if(!['name','city'].every(k=>typeof m[k]==='string'&&m[k].trim()&&m[k].length<=120)||!['LA','TZ'].includes(m.region)||m.consent!==true)throw Error('Invalid profile');
  const O=ArtBridgeApplication.OPTIONS,choices={skills:O.skills,seeking:O.seeking,themes:O.themes,formats:O.formats,partner_regions:['LA','TZ']};
  for(const [k,allowed] of Object.entries(choices))if(!Array.isArray(m[k])||!m[k].length||m[k].some(x=>!allowed.includes(x)))throw Error('Invalid preferences');
  delete m.image;m.sample=false;
 }
 if(r.kind==='project'){
  if(!['title','artist_a','artist_b'].every(k=>typeof m[k]==='string'&&m[k].trim()&&m[k].length<=200)||!['draft','planning','creating','review','archived'].includes(m.stage))throw Error('Invalid project');
  if(m.revenue_a!==''&&(typeof m.revenue_a!=='number'||!Number.isFinite(m.revenue_a)||m.revenue_a<0||m.revenue_a>100))throw Error('Invalid share');
  for(const l of langs)if(r[l]){const v=JSON.parse(r[l]);if(!v||!['brief','deliverables','credit','rights'].every(k=>typeof v[k]==='string'))throw Error('Invalid project translation');}
 }
}
function download(name,body,type='text/plain;charset=utf-8'){const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function api(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok)throw Error(result.error||'Request failed');return result;}
async function saveRecord(record,{translate=false}={}){if(translate){try{record=await translateRecordContent(record);}catch{toast(TRANSLATION_COPY[lang].save);throw Error('Translation failed');}}record.updated_at=new Date().toISOString();validateLocalRecord(record);if(serverMode){record=await api('/api/records',{record,translate:false});}else{const next=records.filter(r=>r.id!==record.id).concat(record);localStorage.setItem(KEY,JSON.stringify(next));}records=records.filter(r=>r.id!==record.id).concat(record);renderDiscover();renderStudio();return record;}
function profiles(){return [...samples,...records.filter(r=>r.kind==='profile').map(r=>({...r.meta,id:r.id,en:r.en,ko:r.ko,sw:r.sw,source_language:r.source_language,sample:false}))];}
