const PROJECT_KEYS=['title','brief','deliverables','credit','rights'];
const PROJECT_LABELS={en:{title:'Project title',brief:'What would you like to create together?',deliverables:'Deliverables',credit:'Artist credit',rights:'Permissions and transformation boundaries'},ko:{title:'프로젝트 제목',brief:'함께 만들고 싶은 것은 무엇인가요?',deliverables:'결과물',credit:'작가 크레딧',rights:'사용 허락과 2차 창작 범위'},sw:{title:'Jina la mradi',brief:'Mngependa kuunda nini pamoja?',deliverables:'Matokeo',credit:'Majina ya wasanii',rights:'Ruhusa na mipaka ya kubadilisha kazi'}};
