 const all=profiles(),partner=all.find(p=>p.id===partnerId),me=all.find(p=>p.id===selectedProfile),m=existing?.meta||{},source=existing?.source_language||lang;
 const columns=langs.map(l=>{const v=exactProjectContent(existing,l);if(l===source){for(const k of ['title','deliverables','credit','rights'])if(v[k]==null)v[k]=m[k]||'';}return `<section class="project-language" lang="${l}"><h3>${{en:'English',ko:'한국어',sw:'Kiswahili'}[l]}</h3>${PROJECT_KEYS.map(k=>`<label class="field"><span>${esc(PROJECT_LABELS[l][k])}</span><textarea name="${l}__${k}" maxlength="${k==='brief'?6000:k==='title'?200:2000}" ${l===source&&['title','brief'].includes(k)?'required':''}>${esc(v[k]||'')}</textarea></label>`).join('')}</section>`;}).join('');
 openModal(heading(t(existing?'editProject':'newProject').replace('+ ',''))+`<p class="helper">${esc(t('newProjectHint'))}</p><form id="project-form" ${existing?`data-id="${esc(existing.id)}"`:''}><div class="field-grid">${field('artistA','artist_a',m.artist_a||me?.name||'','required maxlength="120"')}${field('artistB','artist_b',m.artist_b||partner?.name||'','required maxlength="120"')}<label class="field"><span>${esc(t('sourceLanguage'))}</span><select name="source_language">${languageOptions(source)}</select></label>${field('dueDate','due_date',m.due_date||'','','date')}${field('revenue','revenue_a',m.revenue_a??'','min="0" max="100" step="0.1"','number')}</div><p class="helper">${esc(t('revenueHint'))}</p><p class="notice" id="project-language-status" role="status"></p><div class="project-language-grid">${columns}</div><div class="form-actions"><p class="helper">${esc(t('saveHint'))}</p><button class="button dark" type="submit">${esc(t('createDraft'))}</button></div></form>`);
 const f=$('#project-form');restoreDraft('project-form'+(existing?'__'+existing.id:''),f);
 const status=()=>{const sl=f.elements.source_language.value;for(const l of langs)for(const k of ['title','brief'])f.elements[l+'__'+k].required=l===sl;};f.addEventListener('input',status);status();bindProjectTranslation(f);
